1	package com.example.starter.evidence;
2	
3	import com.example.starter.error.ApiException;
4	import com.example.starter.evidence.dto.LoanCreateRequest;
5	import com.example.starter.evidence.dto.LoanReturnRequest;
6	import com.example.starter.evidence.dto.TransferInitiateRequest;
7	import org.junit.jupiter.api.AfterEach;
8	import org.junit.jupiter.api.Test;
9	import org.springframework.beans.factory.annotation.Autowired;
10	import org.springframework.boot.test.context.SpringBootTest;
11	import org.springframework.http.ResponseEntity;
12	
13	import java.time.Clock;
14	import java.time.Instant;
15	import java.time.LocalDateTime;
16	import java.time.ZoneOffset;
17	import java.util.List;
18	import java.util.UUID;
19	import java.util.concurrent.Callable;
20	import java.util.concurrent.CountDownLatch;
21	import java.util.concurrent.ExecutorService;
22	import java.util.concurrent.Executors;
23	import java.util.concurrent.Future;
24	import java.util.concurrent.TimeUnit;
25	
26	import static org.assertj.core.api.Assertions.assertThat;
27	
28	/**
29	 * 借出相关并发边界测试（真实 H2 行锁与事务）：
30	 * 借出与发起交接、归还与重复归还并发时按事务提交顺序处理，
31	 * 不得出现同时外借与待交接，或归还记录成功而证物状态未变。
32	 */
33	@SpringBootTest
34	class LoanConcurrencyTest {
35	
36	    private static final Instant BASE = Instant.parse("2026-09-22T08:00:00Z");
37	
38	    @Autowired
39	    private EvidenceController controller;
40	
41	    @Autowired
42	    private EvidenceService evidenceService;
43	
44	    @Autowired
45	    private EvidenceClock evidenceClock;
46	
47	    @AfterEach
48	    void resetClock() {
49	        evidenceClock.setClock(Clock.systemUTC());
50	    }
51	
52	    private LocalDateTime due(long seconds) {
53	        return LocalDateTime.ofInstant(BASE.plusSeconds(seconds), ZoneOffset.UTC);
54	    }
55	
56	    private String uniqueKey(String prefix) {
57	        return prefix + "-" + UUID.randomUUID().toString().substring(0, 12);
58	    }
59	
60	    private void intake(String actor, String evidenceKey) {
61	        ResponseEntity<String> response = controller.intake(actor,
62	                new com.example.starter.evidence.dto.IntakeRequest(
63	                        uniqueKey("CMD"), evidenceKey, "CASE-1", "DOCUMENT", "SEAL-1"));
64	        assertThat(response.getStatusCode().value()).isEqualTo(201);
65	    }
66	
67	    private Callable<ResponseEntity<String>> borrow(String actor, String evidenceKey,
68	                                                    String loanKey, String borrower) {
69	        return () -> controller.borrow(actor, evidenceKey,
70	                new LoanCreateRequest(uniqueKey("CMD"), loanKey, borrower, "鉴定用", due(3600)));
71	    }
72	
73	    private Callable<ResponseEntity<String>> initiate(String actor, String evidenceKey,
74	                                                      String toCustodian) {
75	        return () -> controller.initiateTransfer(actor, evidenceKey,
76	                new TransferInitiateRequest(uniqueKey("CMD"), toCustodian));
77	    }
78	
79	    private Callable<ResponseEntity<String>> returns(String actor, String evidenceKey,
80	                                                     String loanKey, boolean sealIntact) {
81	        return () -> controller.returnLoan(actor, evidenceKey,
82	                new LoanReturnRequest(uniqueKey("CMD"), loanKey, sealIntact, "并发归还说明"));
83	    }
84	
85	    /**
86	     * 记录一次并发调用的 HTTP 状态码（业务异常取其携带状态码）。
87	     */
88	    private static final class StatusCall implements Callable<Integer> {
89	        private final CountDownLatch ready;
90	        private final CountDownLatch start;
91	        private final Callable<ResponseEntity<String>> call;
92	
93	        StatusCall(CountDownLatch ready, CountDownLatch start,
94	                   Callable<ResponseEntity<String>> call) {
95	            this.ready = ready;
96	            this.start = start;
97	            this.call = call;
98	        }
99	
100	        @Override
101	        public Integer call() throws Exception {
102	            ready.countDown();
103	            start.await(5, TimeUnit.SECONDS);
104	            try {
105	                return call.call().getStatusCode().value();
106	            } catch (ApiException e) {
107	                return e.status().value();
108	            }
109	        }
110	    }
111	
112	    private List<Integer> runConcurrently(Callable<ResponseEntity<String>> first,
113	                                          Callable<ResponseEntity<String>> second) throws Exception {
114	        ExecutorService executor = Executors.newFixedThreadPool(2);
115	        try {
116	            CountDownLatch ready = new CountDownLatch(2);
117	            CountDownLatch start = new CountDownLatch(1);
118	            Future<Integer> f1 = executor.submit(new StatusCall(ready, start, first));
119	            Future<Integer> f2 = executor.submit(new StatusCall(ready, start, second));
120	            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
121	            start.countDown();
122	            return List.of(f1.get(20, TimeUnit.SECONDS), f2.get(20, TimeUnit.SECONDS));
123	        } finally {
124	            executor.shutdownNow();
125	        }
126	    }
127	
128	    @Test
129	    void concurrentBorrowAndTransferInitiateNeverCoexist() throws Exception {
130	        evidenceClock.setClock(Clock.fixed(BASE, ZoneOffset.UTC));
131	        String evidenceKey = uniqueKey("EV");
132	        intake("alice", evidenceKey);
133	
134	        List<Integer> statuses = runConcurrently(
135	                borrow("alice", evidenceKey, uniqueKey("LOAN"), "bob"),
136	                initiate("alice", evidenceKey, "carol"));
137	
138	        // 恰有一个先提交成功，另一个按提交后的状态被拒绝（409）
139	        assertThat(statuses).containsExactlyInAnyOrder(200, 409);
140	
141	        var chain = evidenceService.custodyChain(evidenceKey);
142	        // 不得同时外借与待交接：状态唯一，且无 ACTIVE 借出与 PENDING 交接并存
143	        boolean activeLoan = chain.loans().stream()
144	                .anyMatch(loan -> loan.status() == LoanStatus.ACTIVE);
145	        boolean pendingTransfer = chain.transfers().stream()
146	                .anyMatch(t -> t.status() == TransferStatus.PENDING);
147	        assertThat(activeLoan).isNotEqualTo(pendingTransfer);
148	        if (activeLoan) {
149	            assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.BORROWED);
150	            assertThat(chain.evidence().custodianId()).isEqualTo("alice");
151	        } else {
152	            assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.TRANSFER_PENDING);
153	        }
154	    }
155	
156	    @Test
157	    void concurrentTwoBorrowsOnlyOneActive() throws Exception {
158	        evidenceClock.setClock(Clock.fixed(BASE, ZoneOffset.UTC));
159	        String evidenceKey = uniqueKey("EV");
160	        intake("alice", evidenceKey);
161	
162	        List<Integer> statuses = runConcurrently(
163	                borrow("alice", evidenceKey, uniqueKey("LOAN"), "bob"),
164	                borrow("alice", evidenceKey, uniqueKey("LOAN"), "carol"));
165	
166	        assertThat(statuses).containsExactlyInAnyOrder(200, 409);
167	
168	        var chain = evidenceService.custodyChain(evidenceKey);
169	        assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.BORROWED);
170	        assertThat(chain.loans()).hasSize(1);
171	        assertThat(chain.loans().get(0).status()).isEqualTo(LoanStatus.ACTIVE);
172	    }
173	
174	    @Test
175	    void concurrentReturnsOnlyOneCompletesAndStateMatchesRecord() throws Exception {
176	        evidenceClock.setClock(Clock.fixed(BASE, ZoneOffset.UTC));
177	        String evidenceKey = uniqueKey("EV");
178	        String loanKey = uniqueKey("LOAN");
179	        intake("alice", evidenceKey);
180	        ResponseEntity<String> borrowed = controller.borrow("alice", evidenceKey,
181	                new LoanCreateRequest(uniqueKey("CMD"), loanKey, "bob", "鉴定用", due(3600)));
182	        assertThat(borrowed.getStatusCode().value()).isEqualTo(200);
183	
184	        // 两个独立命令并发归还同一笔借出（不同 commandKey，非幂等重放）
185	        List<Integer> statuses = runConcurrently(
186	                returns("alice", evidenceKey, loanKey, true),
187	                returns("alice", evidenceKey, loanKey, true));
188	
189	        assertThat(statuses).containsExactlyInAnyOrder(200, 409);
190	
191	        var chain = evidenceService.custodyChain(evidenceKey);
192	        // 归还记录成功则证物必须同事务变为 SEALED；只有一笔借出、一条核验、一次归还
193	        assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.SEALED);
194	        assertThat(chain.evidence().custodianId()).isEqualTo("alice");
