 * 完成销毁后保管链只读、幂等与失败不占键（固定时钟驱动，真实 H2）。
 */
@SpringBootTest
@AutoConfigureMockMvc
class DestructionApiTest {

    private static final String ACTOR_HEADER = "X-Actor-Id";

    /** 测试基准时刻（UTC）。 */
